mapper.select:
SELECT O.ORDER_ID, O.ORDER_TYPE, O.ORDER_STATUS, O.TOTAL_PRICE, O.DISCOUNT_AMT, O.CREATED_AT, O.USER_ID, OI.ITEM_ID, P.PRODUCT_ID, P.PRODUCT_NAME, B.BRAND_NAME, C.CATEGORY_NAME, U.USER_NAME AS RECEIVER_NAME, U.USER_PHONE AS RECEIVER_PHONE, A.ZIPCODE, A.ADDRESS AS DELIVERY_ADDR, A.DETAILED_ADDRESS AS DELIVERY_DETAIL_ADDR,
/* 결제 */ COALESCE(PH.PAY_TYPE, 'CARD') AS PAY_METHOD, COALESCE(PM.PAID_AT, O.CREATED_AT) AS PAY_DATE,
/* 상품 */ P.PRODUCT_ID, P.PRODUCT_NAME, B.BRAND_NAME AS BRAND_NAME, C.CATEGORY_NAME AS CATEGORY_NAME,
OI.UNIT_PRICE AS ITEM_PRICE, OI.QUANTITY AS ITEM_COUNT, O.ORDER_TYPE AS ITEM_TYPE, OI.START_DATE, OI.END_DATE,
/* 대표 이미지 */ (SELECT PI.IMG_URL FROM PRODUCT_IMG PI WHERE PI.PRODUCT_ID = P.PRODUCT_ID AND PI.IS_MAIN = 'Y' LIMIT 1) AS IMG_URL
FROM ORDERS O
INNER JOIN ORDER_ITEM OI ON O.ORDER_ID = OI.ORDER_ID
INNER JOIN PRODUCT P ON OI.PRODUCT_ID = P.PRODUCT_ID
/* 🔥 추가된 부분 */ LEFT JOIN BRAND B ON P.BRAND_ID = B.BRAND_ID
LEFT JOIN PRODUCT_CATEGORY C ON P.CATEGORY_ID = C.CATEGORY_ID
INNER JOIN USER U ON O.USER_ID = U.USER_ID
LEFT JOIN USER_ADDRESS A ON O.USER_ID = A.USER_ID AND A.DEFAULT_YN = 'Y'
LEFT JOIN PAYMENT PM ON O.ORDER_ID = PM.ORDER_ID
LEFT JOIN PAYMENT_HISTORY PH ON PM.PAY_ID = PH.TARGET_PAY_ID AND PH.NEW_STATUS = 'PAID'
WHERE O.ORDER_ID = #{orderId}
AND O.USER_ID = #{userId}
